import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.y1bVONfd.js";const p=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),o={name:"architecture.md"};function i(s,e,c,n,l,u){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Proofmark is currently organized around a local-first dry-run path.</p><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><ul><li>Source database sampling is read-only during dry runs.</li><li>Production data and credentials stay in the user&#39;s environment.</li><li>Demo evidence must be explicit, never silent fallback for real workflows.</li><li>The CLI owns developer workflow; the dashboard visualizes evidence state.</li><li>Business strategy lives outside the repo.</li></ul><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Files</th><th>Responsibility</th></tr></thead><tbody><tr><td>CLI</td><td><code>bin/cli.ts</code>, <code>src/commands/*</code></td><td>Command parsing, project init, dry-run output</td></tr><tr><td>Config</td><td><code>src/config/load.ts</code>, <code>src/config/types.ts</code></td><td><code>proofmark.json</code> loading and validation</td></tr><tr><td>Introspection</td><td><code>src/introspection/prismaAdapter.ts</code></td><td>Prisma schema parsing and rule inference</td></tr><tr><td>Sampling</td><td><code>src/sync/postgresSampler.ts</code></td><td>Read-only Postgres sampling for configured fields</td></tr><tr><td>Masking</td><td><code>src/sync/masking.ts</code></td><td>Deterministic local replacement values</td></tr><tr><td>Evidence</td><td><code>src/sync/evidence.ts</code>, <code>src/sync/dashboardData.ts</code></td><td>Shared dry-run rows, certificates, dashboard data</td></tr><tr><td>Dashboard</td><td><code>app/server/syncDashboard.ts</code>, <code>app/routes/*</code></td><td>TanStack Start server function and UI</td></tr></tbody></table><h2 id="current-stack-choices" tabindex="-1">Current Stack Choices <a class="header-anchor" href="#current-stack-choices" aria-label="Permalink to &quot;Current Stack Choices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Choice</th><th>Reason</th></tr></thead><tbody><tr><td>TypeScript CLI</td><td>Shared types with dashboard and strict local checks.</td></tr><tr><td>Prisma-first introspection</td><td>Narrow target stack and schema metadata is available locally.</td></tr><tr><td>Postgres-first sampling</td><td>Common target database and supported by <code>pg</code>.</td></tr><tr><td><code>pg</code> pool</td><td>Small direct dependency for read-only SQL queries.</td></tr><tr><td>TanStack Start dashboard</td><td>Existing app surface with server functions and React Router integration.</td></tr><tr><td>Deterministic masks</td><td>Stable output makes CLI reports, screenshots, and tests reproducible.</td></tr></tbody></table><h2 id="dry-run-flow" tabindex="-1">Dry-Run Flow <a class="header-anchor" href="#dry-run-flow" aria-label="Permalink to &quot;Dry-Run Flow&quot;">​</a></h2><ol><li>Load <code>proofmark.json</code>.</li><li>Resolve <code>process.env.*</code> source URL references.</li><li>Parse the configured Prisma schema.</li><li>Map configured model fields to table and column names.</li><li>Build quoted SQL identifier queries.</li><li>Sample source rows read-only.</li><li>Apply local masking strategies.</li><li>Produce evidence rows and certificate state.</li><li>Print CLI report or render dashboard state.</li></ol><h2 id="security-notes" tabindex="-1">Security Notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security Notes&quot;">​</a></h2><ul><li>SQL values are parameterized where values are used.</li><li>Table and column identifiers are derived from config/schema and quoted before interpolation.</li><li>Source URLs are resolved for connection use but not printed.</li><li><code>--demo</code> is explicit; missing config fails the CLI dry run.</li><li>The dashboard renders an unconfigured state when no project config exists.</li></ul>',12)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
